//! Throwaway cross-check between the wallet (Dart) and the backend (Rust).
//!
//! `fixture`: prints a credential issued by the real `Issuer` (Harbour Club) to the fixture holder.
//! `verify`:  issues a fresh credential, has the wallet build presentations through
//!            `app/tool/crosscheck_present.dart`, and runs them through the real `Verifier`.
use std::process::Command;
use std::sync::Arc;

use credentials_backend::issuer::{CredentialRequest, IssuedCredential, Issuer};
use credentials_backend::resolver::{did_key_for, Resolver};
use credentials_backend::store::Store;
use credentials_backend::transport::StaticTransport;
use credentials_backend::verifier::{Submission, Verifier, VerifyError};
use ed25519_dalek::SigningKey;
use serde_json::{json, Value};

const HARBOUR_DID: &str = "did:web:members.harbourclub.example";
const HARBOUR_KEY_ID: &str = "did:web:members.harbourclub.example#key-1";
const HARBOUR_SEED: &str = "9f3688f6e8b93b0cfa3b11c28fbc25fe5440192ed82835e7fe3ab590f03f6c75";
const HARBOUR_DOC: &str = include_str!("../../reference/infra/hosted-dids/members.harbourclub.example/.well-known/did.json");
const DOMAIN: &str = "door.harbourclub.example";

fn seed(hex: &str) -> [u8; 32] {
    let mut out = [0u8; 32];
    for (i, b) in out.iter_mut().enumerate() {
        *b = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap();
    }
    out
}

fn issue(store: &Store, issued_at: i64, expires_at: i64) -> IssuedCredential {
    let holder = did_key_for(&SigningKey::from_bytes(&[7; 32]).verifying_key());
    let issuer = Issuer::new(HARBOUR_DID, HARBOUR_KEY_ID, &seed(HARBOUR_SEED));
    let request = CredentialRequest {
        holder,
        credential_type: "MembershipCredential".into(),
        claims: vec![
            ("member".into(), json!(true)),
            ("memberId".into(), json!("M-20417")),
            ("name".into(), json!("Ada \"Pärk\"\n\u{1F600}")),
            ("birthDate".into(), json!("1990-04-12")),
        ],
        issued_at,
        not_before: None,
        expires_at,
    };
    issuer.issue(store, &request).unwrap()
}

fn issuance_json(issued: &IssuedCredential) -> Value {
    json!({ "credential": issued.credential, "disclosures": issued.disclosures })
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs() as i64;
    let store = Arc::new(Store::from_onboarding_data().unwrap());
    if mode == "fixture" {
        // 2026-01-01 .. 2100-01-01
        let issued = issue(&store, 1_767_225_600, 4_102_444_800);
        println!("holder {}", did_key_for(&SigningKey::from_bytes(&[7; 32]).verifying_key()));
        println!("{}", serde_json::to_string_pretty(&issuance_json(&issued)).unwrap());
        return;
    }

    let issued = issue(&store, now - 30 * 86_400, now + 180 * 86_400);
    let dir = std::env::temp_dir().join(format!("crosscheck-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("issuance.json"), issuance_json(&issued).to_string()).unwrap();

    let status = Command::new("dart")
        .current_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/../app"))
        .args(["run", "tool/crosscheck_present.dart"])
        .arg(&dir)
        .status()
        .unwrap();
    assert!(status.success(), "wallet side failed");

    let transport = StaticTransport::default().with("https://members.harbourclub.example/.well-known/did.json", HARBOUR_DOC);
    let verifier = Verifier::new(Resolver::new(Arc::new(transport)), store.clone());
    let mut request_n = 0;
    let mut door = |vp: &Value, nonce: &str, domain: &str| {
        request_n += 1;
        verifier.verify_presentation(&Submission { request_id: format!("req-{request_n}"), presentation: vp.clone() }, nonce, domain)
    };
    let read = |name: &str| -> Value { serde_json::from_slice(&std::fs::read(dir.join(name)).unwrap()).unwrap() };

    let mut failures = 0;
    let mut check = |label: &str, ok: bool, detail: String| {
        println!("{} {label}: {detail}", if ok { "PASS" } else { "FAIL" });
        if !ok {
            failures += 1;
        }
    };

    for (file, nonce, expected_claims) in [("vp-member.json", "n-member-01", vec!["member"]), ("vp-name.json", "n-name-02", vec!["name"])] {
        let vp = read(file);
        match door(&vp, nonce, DOMAIN) {
            Ok(v) => {
                let claims: Vec<&str> = v.claims.keys().map(String::as_str).collect();
                check(&format!("{file} accepted by the real Verifier"), claims == expected_claims, format!("claims disclosed {claims:?}, values {:?}", v.claims));
            }
            Err(e) => check(&format!("{file} accepted by the real Verifier"), false, format!("{e:?}")),
        }
    }

    let vp = read("vp-member.json");
    let expect = |r: Result<_, VerifyError>, want: fn(&VerifyError) -> bool| match r {
        Err(e) => (want(&e), format!("{e:?}")),
        Ok(_) => (false, "ACCEPTED".to_string()),
    };

    let (ok, d) = expect(door(&vp, "n-some-other-scan", DOMAIN), |e| matches!(e, VerifyError::NonceMismatch));
    check("presented to a scan with another nonce", ok, d);
    let mut t = vp.clone();
    t["nonce"] = json!("n-some-other-scan");
    let (ok, d) = expect(door(&t, "n-some-other-scan", DOMAIN), |e| matches!(e, VerifyError::BadSignature(_)));
    check("nonce rewritten after signing", ok, d);

    let (ok, d) = expect(door(&vp, "n-member-01", "door.elsewhere.example"), |e| matches!(e, VerifyError::DomainMismatch));
    check("presented to another domain", ok, d);
    let mut t = vp.clone();
    t["domain"] = json!("door.elsewhere.example");
    let (ok, d) = expect(door(&t, "n-member-01", "door.elsewhere.example"), |e| matches!(e, VerifyError::BadSignature(_)));
    check("domain rewritten after signing", ok, d);

    let mut t = vp.clone();
    t["disclosures"][0]["value"] = json!(false);
    let (ok, d) = expect(door(&t, "n-member-01", DOMAIN), |e| matches!(e, VerifyError::BadSignature(_) | VerifyError::UndisclosedClaim(_)));
    check("disclosure value changed", ok, d);
    let mut t = vp.clone();
    let birth = issued.disclosures.iter().find(|d| d.name == "birthDate").unwrap();
    t["disclosures"].as_array_mut().unwrap().push(serde_json::to_value(birth).unwrap());
    let (ok, d) = expect(door(&t, "n-member-01", DOMAIN), |e| matches!(e, VerifyError::BadSignature(_)));
    check("disclosure added after signing", ok, d);

    std::fs::remove_dir_all(&dir).unwrap();
    println!("{} failure(s)", failures);
    std::process::exit(if failures == 0 { 0 } else { 1 });
}
EOF
