import 'package:credentials_app/src/issuer_client.dart';
import 'package:credentials_app/src/presentation_request.dart';
import 'package:credentials_app/src/wallet_service.dart';

class _NoIssuer implements IssuerClient {
  @override
  Future<HeldCredential> issue({required String holderDid, required String credentialType}) =>
      throw UnsupportedError('not used');
}

Map<String, dynamic> request(String claim, String nonce) => {
  'client_id': 'door.harbourclub.example',
  'nonce': nonce,
  'dcql_query': {
    'credentials': [
      {
        'id': 'membership',
        'format': 'ldp_vc',
        'claims': [
          {'path': ['credentialSubject', claim]},
        ],
      },
    ],
  },
};

Future<void> main(List<String> args) async {
  final dir = args.single;
  final issuance = jsonDecode(File('$dir/issuance.json').readAsStringSync()) as Map<String, dynamic>;
