  final wallet = WalletService(
    issuer: _NoIssuer(),
    store: CredentialStore()..save(held),
    newKey: () => HolderKey.fromSeed(Uint8List.fromList(List.filled(32, 7))),
  );
  for (final (file, claim, nonce) in [('vp-member.json', 'member', 'n-member-01'), ('vp-name.json', 'name', 'n-name-02')]) {
