Map<String, dynamic> request(String claim, String nonce) => {
  'client_id': 'door.harbourclub.example',
  'nonce': nonce,
  'dcql_query': {
    'credentials': [
      {
        'id': 'membership',
        'format': 'ldp_vc',
        'claims': [
          {'path': ['credentialSubject', claim]},
        ],
      },
    ],
  },
};

Future<void> main(List<String> args) async {
  final dir = args.single;
  final issuance = jsonDecode(File('$dir/issuance.json').readAsStringSync()) as Map<String, dynamic>;
  final held = HeldCredential.fromIssuance(issuance);
  final wallet = WalletService(
    issuer: _NoIssuer(),
    store: CredentialStore()..save(held),
    newKey: () => HolderKey.fromSeed(Uint8List.fromList(List.filled(32, 7))),
  );
  for (final (file, claim, nonce) in [('vp-member.json', 'member', 'n-member-01'), ('vp-name.json', 'name', 'n-name-02')]) {
    final vp = await wallet.createPresentation(held.id, PresentationRequest.fromJson(request(claim, nonce)));
    File('$dir/$file').writeAsStringSync(jsonEncode(vp));
  }
  print('wallet: wrote presentations for ${held.id}');
}
